/**
 * Native Adapter for WordPlay Game Engine
 *
 * React Native/Expo platform-specific implementation, mirroring
 * apps/web's `browserAdapter.ts` exactly (same class shape, same
 * dependency-injection wiring) but loading word-list data from bundled
 * JSON assets (`assets/data/*.json`, generated by
 * `scripts/generate-native-word-data.cjs` from apps/web's public/ files)
 * instead of `fetch()`ing them over HTTP - there is no static-file server
 * to fetch from on-device.
 */

import type { WordDataDependencies, ValidationResult, BotDependencies, ScoringOptions, ValidationOptions, BotOptions } from '@wordplay/engine/interfaces';
import { validateWordWithDependencies, isValidDictionaryWordWithDependencies } from '@wordplay/engine/dictionary';
import { calculateScore, getScoreForMove, isValidMove } from '@wordplay/engine/scoring';
import { generateBotMoveWithDependencies } from '@wordplay/engine/bot';
import type { BotResult } from '@wordplay/engine/interfaces';
import type {
  GameStateDictionaryDependencies,
  GameStateScoringDependencies,
  GameStateBotDependencies,
  GameStateDependencies
} from '@wordplay/engine/gamestate';

// Metro bundles `require()`d .json files directly into the app - no
// runtime file I/O needed, unlike the browser adapter's `fetch()` calls.
// eslint-disable-next-line @typescript-eslint/no-var-requires
const enableWordsList: string[] = require('../../assets/data/enable1-words.json');
const slangData: { words?: string[] } = require('../../assets/data/slang-words.json');
const profanityData: { words?: string[] } = require('../../assets/data/profanity-words.json');
const properNounData: { words?: string[] } = require('../../assets/data/common-proper-nouns.json');
const seussCanonicalData: { words?: string[] } = require('../../assets/data/seuss-words-canonical.json');
const seussInventedData: { words?: string[] } = require('../../assets/data/seuss-words-invented.json');

/**
 * Native-specific word data implementation.
 * Loads dictionary from bundled JSON assets (synchronous, no network).
 */
class NativeWordData implements WordDataDependencies {
  public enableWords: Set<string> = new Set();
  public slangWords: Set<string> = new Set();
  public profanityWords: Set<string> = new Set();
  public properNounWords: Set<string> = new Set();
  public seussCanonicalWords: Set<string> = new Set();
  public seussInventedWords: Set<string> = new Set();
  public wordCount: number = 0;
  private wordsByLength: Map<number, string[]> = new Map();
  private loaded = false;
  private loadingPromise: Promise<void>;

  constructor() {
    this.loadingPromise = this.loadDictionary();
  }

  public hasWord(word: string): boolean {
    const upperWord = word.toUpperCase();
    return this.enableWords.has(upperWord) || this.slangWords.has(upperWord) || this.properNounWords.has(upperWord);
  }

  public isLoaded(): boolean {
    return this.loaded;
  }

  /**
   * Wait for dictionary to be loaded. Loading is synchronous (bundled
   * assets, no network), so this resolves on the next microtask - kept as
   * an async method for API parity with `BrowserWordData.waitForLoad()`,
   * since consumers (adapters, hooks) already await it unconditionally.
   */
  public async waitForLoad(): Promise<void> {
    await this.loadingPromise;
  }

  public getRandomWordByLength(length: number): string | null {
    if (!this.loaded) {
      console.warn('NativeWordData: Dictionary not loaded yet, returning null');
      return null;
    }
    const words = this.wordsByLength.get(length);
    if (!words || words.length === 0) {
      return null;
    }
    const nonProfaneWords = words.filter(word => !this.profanityWords.has(word));
    const pool = nonProfaneWords.length > 0 ? nonProfaneWords : words;
    const randomIndex = Math.floor(Math.random() * pool.length);
    return pool[randomIndex];
  }

  private async loadDictionary(): Promise<void> {
    if (this.loaded) return;
    try {
      const wordList = enableWordsList;

      this.enableWords = new Set(wordList);
      this.wordCount = this.enableWords.size;

      this.wordsByLength.clear();
      for (const word of wordList) {
        const length = word.length;
        if (!this.wordsByLength.has(length)) {
          this.wordsByLength.set(length, []);
        }
        this.wordsByLength.get(length)!.push(word);
      }

      this.slangWords = new Set(slangData.words || []);
      this.profanityWords = new Set(profanityData.words || []);
      this.properNounWords = new Set(properNounData.words || []);
      this.seussCanonicalWords = new Set(seussCanonicalData.words || []);
      this.seussInventedWords = new Set(seussInventedData.words || []);

      this.loaded = true;
    } catch (error) {
      console.error('Failed to load dictionary from bundled assets:', error);
      this.initializeFallback();
    }
  }

  private initializeFallback(): void {
    const fallbackWords = [
      'CAT', 'DOG', 'WORD', 'GAME', 'PLAY', 'MOVE', 'TURN', 'SCORE',
      'CATS', 'DOGS', 'WORDS', 'GAMES', 'PLAYS', 'MOVES', 'TURNS', 'SCORES',
      'HELLO', 'WORLD', 'TEST', 'TIME', 'GOOD', 'BAD', 'NEW', 'OLD',
      'BIG', 'SMALL', 'HOT', 'COLD', 'LIGHT', 'DARK', 'HAPPY', 'SAD'
    ];

    this.enableWords = new Set(fallbackWords);
    this.wordCount = this.enableWords.size;
    this.slangWords = new Set(['BRUH', 'YEAH', 'YEET', 'SELFIE']);
    this.profanityWords = new Set();
    this.properNounWords = new Set();
    this.seussCanonicalWords = new Set();
    this.seussInventedWords = new Set();

    this.loaded = true;
  }
}

// =============================================================================
// NATIVE DEPENDENCY IMPLEMENTATIONS
// =============================================================================

let nativeWordData: NativeWordData | null = null;

function getNativeWordData(): NativeWordData {
  if (!nativeWordData) {
    nativeWordData = new NativeWordData();
  }
  return nativeWordData;
}

const nativeDictionaryDependencies: GameStateDictionaryDependencies = {
  validateWord: (word: string, options?: ValidationOptions): ValidationResult => {
    return validateWordWithDependencies(word, getNativeWordData(), options);
  },

  getRandomWordByLength: (length: number): string | null => {
    return getNativeWordData().getRandomWordByLength(length);
  },

  getRandomSeussCanonicalWord: (length?: number): string | null => {
    let words = Array.from(getNativeWordData().seussCanonicalWords);
    if (length !== undefined) {
      words = words.filter(w => w.length === length);
    }
    if (words.length === 0) return null;
    return words[Math.floor(Math.random() * words.length)];
  }
};

const nativeScoringDependencies: GameStateScoringDependencies = {
  calculateScore: (fromWord: string, toWord: string, options?: ScoringOptions) => {
    return calculateScore(fromWord, toWord, options);
  },

  getScoreForMove: (fromWord: string, toWord: string, keyLetters?: string[]): number => {
    return getScoreForMove(fromWord, toWord, keyLetters);
  },

  isValidMove: (fromWord: string, toWord: string): boolean => {
    return isValidMove(fromWord, toWord);
  }
};

const nativeBotDependencies: GameStateBotDependencies = {
  generateBotMove: async (word: string, options?: BotOptions): Promise<BotResult> => {
    const wordData = getNativeWordData();
    const botDeps: BotDependencies = {
      validateWord: nativeDictionaryDependencies.validateWord,
      isValidDictionaryWord: (word: string): boolean => {
        return isValidDictionaryWordWithDependencies(word, wordData);
      },
      getRandomWordByLength: nativeDictionaryDependencies.getRandomWordByLength,
      getWordCount: (): number => wordData.wordCount,

      getTimestamp: (): number => Date.now(),
      random: (): number => Math.random(),
      log: (message: string): void => console.log(`[Bot] ${message}`),

      getScoreForMove: (fromWord: string, toWord: string, keyLetters?: string[]): number => {
        return getScoreForMove(fromWord, toWord, keyLetters || []);
      },
      calculateScore: (fromWord: string, toWord: string, options?: ScoringOptions) => {
        return calculateScore(fromWord, toWord, options);
      },

      isProfanity: (word: string): boolean => {
        return wordData.profanityWords.has(word.toUpperCase());
      },

      isSeussWord: (word: string): boolean => {
        const w = word.toUpperCase();
        return wordData.seussCanonicalWords.has(w) || wordData.seussInventedWords.has(w);
      },

      isSeussCanonicalWord: (word: string): boolean => {
        return wordData.seussCanonicalWords.has(word.toUpperCase());
      }
    };
    return generateBotMoveWithDependencies(word, botDeps, { ...options, botId: options?.botId });
  }
};

const nativeGameDependencies: GameStateDependencies = {
  ...nativeDictionaryDependencies,
  ...nativeScoringDependencies,
  ...nativeBotDependencies
};

// =============================================================================
// NATIVE ADAPTER API
// =============================================================================

/**
 * Native Platform Adapter.
 * Main interface for React Native-specific WordPlay engine integration.
 * Mirrors `BrowserAdapter`'s public API exactly.
 */
export class NativeAdapter {
  private static instance: NativeAdapter | null = null;
  private wordData: NativeWordData;
  private initialized: boolean = false;

  private constructor() {
    this.wordData = getNativeWordData();
  }

  static getInstance(): NativeAdapter {
    if (!NativeAdapter.instance) {
      NativeAdapter.instance = new NativeAdapter();
    }
    return NativeAdapter.instance;
  }

  async initialize(): Promise<void> {
    if (this.initialized) {
      return;
    }
    await this.wordData.waitForLoad();
    this.initialized = true;
  }

  getGameDependencies(): GameStateDependencies {
    if (!this.initialized) {
      console.warn('NativeAdapter not initialized. Call initialize() first.');
    }
    return nativeGameDependencies;
  }

  getDictionaryDependencies(): GameStateDictionaryDependencies {
    return nativeDictionaryDependencies;
  }

  getScoringDependencies(): GameStateScoringDependencies {
    return nativeScoringDependencies;
  }

  getBotDependencies(): GameStateBotDependencies {
    return nativeBotDependencies;
  }

  get isInitialized(): boolean {
    return this.initialized;
  }

  getDictionaryStatus(): { loaded: boolean; wordCount: number } {
    return {
      loaded: this.wordData.isLoaded(),
      wordCount: this.wordData.enableWords.size
    };
  }

  getWordData(): NativeWordData {
    return this.wordData;
  }
}

// =============================================================================
// CONVENIENCE FUNCTIONS
// =============================================================================

export async function createNativeAdapter(): Promise<NativeAdapter> {
  const adapter = NativeAdapter.getInstance();
  await adapter.initialize();
  return adapter;
}

export function getNativeGameDependencies(): GameStateDependencies {
  return NativeAdapter.getInstance().getGameDependencies();
}

export default NativeAdapter;
